// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: a plain EOA actor, a positive fundable amount.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(uint160(actor) > uint160(0x100)); // avoid precompiles
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);          // actor can deposit
        vm.deal(address(this), 0);

        vm.startPrank(actor);
        // deposit via the fallback
        (bool depOk, ) = address(c).call{value: amount}("");
        require(depOk, "deposit failed");

        // first withdraw: must succeed on both reference and mutant
        bool ok1; try c.withdraw() { ok1 = true; } catch { ok1 = false; }
        // second withdraw: reference releases the lock -> succeeds;
        // mutant keeps the lock set forever -> reverts
        bool ok2; try c.withdraw() { ok2 = true; } catch { ok2 = false; }
        vm.stopPrank();

        assertTrue(ok1 && ok2, "a completed withdraw must release the lock so the next withdraw succeeds");
    }
}
